(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.32)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.5)*6 + Math.cos(sy*0.03+t*0.4)*4;
  const w2y = Math.cos(sy*0.025+t*0.45)*6 + Math.sin(sx*0.028-t*0.35)*4;
  const dx = sx+w2x, dy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9, 0.7],
    [60+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.6+5)*50, 0.085, 2.1, 1.3],
    [420+Math.cos(t*0.45+2)*60, 200+Math.sin(t*0.8+1)*70, 0.075, 1.8, 0.85]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp,w]=src[i];
    const d=Math.sqrt((dx-sX)**2+(dy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.5)*w;
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2,f2,sp2]=src[j];
      const mx=(sX+sX2)/2+Math.sin(t*0.4+i+j)*30;
      const my=(sY+sY2)/2+Math.cos(t*0.35+i*j)*25;
      const dd=Math.sqrt((dx-mx)**2+(dy-my)**2);
      cross+=Math.sin(dd*(f+f2)*0.4-t*(sp+sp2)*0.3)*0.15;
    }
  }
  const wT=src.reduce((s,v)=>s+v[4],0);
  const act=aS/wT, inh=iS/wT;
  const bg=(Math.sin(dx*0.035+dy*0.022+t*0.9)+Math.sin(dx*0.028-dy*0.038+t*1.2))/2+Math.sin((dx+dy)*0.1+t*2.8)*0.15+Math.sin((dx-dy)*0.09-t*2.2)*0.15;
  const dist=Math.sqrt((dx-cx)**2+(dy-cy)**2), ang=Math.atan2(dy-cy,dx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.6)+Math.sin(dist*0.035+ang*4.5-t*1.3))*0.35;
  const radial=Math.sin(dist*0.06-t*2.5)*Math.cos(ang*2-t*0.8)*0.2;
  const laplacian=Math.sin(dx*0.12+t)*Math.sin(dy*0.12-t*0.7)+Math.sin(dx*0.08-dy*0.1+t*1.5)*0.5;
  const diffusion=Math.tanh((act-inh*0.65+bg*0.25+spiral+cross+radial+laplacian*0.15)*2.0);
  const micro=Math.sin(dx*0.22+t*1.5)*Math.sin(dy*0.22-t*1.2)*0.12+Math.sin((dx+dy)*0.18+t*3)*0.08;
  const cell=Math.tanh((Math.sin(dx*0.13)*Math.sin(dy*0.13)+Math.sin((dx+dy)*0.09+t)*0.4)*1.3)*0.25;
  const blend=diffusion*0.7+cell*0.2+micro*0.1;
  const v=blend*0.5+0.5;
  const pal=[[5,12,52],[10,45,85],[15,85,120],[18,135,145],[45,175,160],[160,195,110],[220,190,80],[235,145,65],[220,95,70],[180,55,75],[120,30,65],[55,15,50],[5,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const energy=Math.abs(diffusion);
  const lum=0.85+energy*0.15+Math.sin(blend*Math.PI)*0.1;
  const edge=Math.abs(diffusion)>0.65?1.12:Math.abs(diffusion)>0.4?1.05:1.0;
  const shimmer=Math.sin(t*4+dx*0.05+dy*0.03)*0.03*energy;
  return [
    Math.min(255,Math.max(0,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+shimmer*40)|0)),
    Math.min(255,Math.max(0,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+shimmer*60)|0)),
    Math.min(255,Math.max(0,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+shimmer*80)|0))
  ];
}
